import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as n,o,ag as t,G as r}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Cindy source code walkthrough: how the three harnesses are wired into one workspace","description":"Read the source of makecindy/cindy to make four things clear: Codex is implemented directly in maker-core rather than as a separate package; phone-to-computer control relies on a deny-by-default allowlist; Orca uses MCP to let one Lead direct several Workers; the various model protocols are translated for each other by a local loopback proxy. Includes a repository map, the steps to run it from source, and three lists: verified, inferred and unknown.","frontmatter":{"title":"Cindy source code walkthrough: how the three harnesses are wired into one workspace","description":"Read the source of makecindy/cindy to make four things clear: Codex is implemented directly in maker-core rather than as a separate package; phone-to-computer control relies on a deny-by-default allowlist; Orca uses MCP to let one Lead direct several Workers; the various model protocols are translated for each other by a local loopback proxy. Includes a repository map, the steps to run it from source, and three lists: verified, inferred and unknown.","domain":"product","tags":["source-code","electron","harness","device-link"],"role":"deep-dive","pageClass":"wide-figures","source_revision":"6fdec7fb89b955be548c3f5cc9a42d83bf174aa3"},"headers":[],"relativePath":"products/cindy/source.md","filePath":"products/cindy/source.md","lastUpdated":1795792629000}'),d={name:"products/cindy/source.md"};function h(c,e,l,p,k,g){const s=i("DocDiagram");return o(),n("div",null,[e[0]||(e[0]=t("",29)),r(s,{src:"/diagrams/cindy-session-flow.en.svg",alt:"This sequence diagram answers one question by number: when you send a message from the UI, which objects does it pass through, in what order, before the harness runs it, and how does the result come back to the UI. There are six vertical lanes, left to right: the UI, that is the Renderer; the preload bridge, that is preload; the main process, whose lane names both the IPC handler and the input coordinator; Maker and Session, both in maker-core; the harness adapter; and the harness subprocess. The local SQLite database is the ninth object, drawn as a callout box inside the main-process lane. The number in each round badge is the order; when one number has several arrows, that step is relayed through several objects. Solid arrows are commands or calls; dashed arrows are events, broadcasts and returns. Step 1: the UI invokes maker:send through the preload bridge, carrying the sessionId and the message, and the call reaches the handler registered with ipcMain.handle in the main process. Step 2: the main process hands the input to the input coordinator, which queues it, saves it to the database and checks whether this task already has a running turn. Step 3: the coordinator gets or resumes the matching Session through Maker. Step 4: Session.send enters dispatchSend, which confirms that no turn is running and reserves an id for this turn. Step 5: Session calls handle.send and enters the harness adapter. Step 6: the adapter translates the message into that harness's own protocol and sends it to the subprocess: turn/start for Codex, SDK query for Claude Code, RPC for Pi. Step 7: the subprocess runs: it calls the model, reads and writes files, and runs commands. Step 8: the raw harness output reaches the adapter, which translates it into unified events such as text, tool_use, tool_result and turn_diff and passes them to Session. Step 9: Session dispatches the events to listeners; the main process writes the message to the local SQLite database and broadcasts the events back to the UI. Step 10: an action that needs confirmation travels as interaction_request through Session and the main process back to the UI, where it waits for the user's decision; the decision then goes through the main process and Session to the adapter, which passes it back to the subprocess; when no matching subscriber is found it is treated as a rejection. Step 11: the subprocess reports that the turn ended, Session receives done, and the UI is enabled for input again. This diagram omits: the server or cloud, because a local task turn does not go through the Cindy service; the phone and Device Link, which are a separate path; any timing numbers; and the specific database functions and table layout.",width:1020,lang:"en"}),e[1]||(e[1]=t("",69))])}const E=a(d,[["render",h]]);export{f as __pageData,E as default};
